Bedrock Converse-format message converter for GenAI Semantic Convention export.

Translates Bedrock Converse API request/response structures into the OpenTelemetry
GenAI semantic convention attributes: gen_ai.input.messages, gen_ai.output.messages,
system instructions, request params, and tool definitions.
"""

import base64
import json
from typing import Any

from mlflow.tracing.constant import GenAiSemconvKey
from mlflow.tracing.export.genai_semconv.converter import GenAiSemconvConverter


class BedrockConverseConverter(GenAiSemconvConverter):
    def convert_inputs(self, inputs: dict[str, Any]) -> list[dict[str, Any]] | None:
        messages = inputs.get("messages")
        if not isinstance(messages, list):
            return None
        return [_convert_message(m) for m in messages]

    def convert_system_instructions(self, inputs: dict[str, Any]) -> list[dict[str, Any]] | None:
        system = inputs.get("system")
        if isinstance(system, str):
            return [{"type": "text", "content": system}]
        if isinstance(system, list):
            return [_convert_system_block(b) for b in system]
        return None

    def convert_outputs(self, outputs: dict[str, Any]) -> list[dict[str, Any]] | None:
        output = outputs.get("output")
        if not isinstance(output, dict):
            return None
        message = output.get("message")
        if not isinstance(message, dict):
            return None
        return [_convert_message(message)]

    def extract_request_params(self, inputs: dict[str, Any]) -> dict[str, Any]:
        params: dict[str, Any] = {}
        inference_config = inputs.get("inferenceConfig") or {}
        if (temperature := inference_config.get("temperature")) is not None:
            params[GenAiSemconvKey.REQUEST_TEMPERATURE] = temperature
        if (max_tokens := inference_config.get("maxTokens")) is not None:
            params[GenAiSemconvKey.REQUEST_MAX_TOKENS] = max_tokens
        if (top_p := inference_config.get("topP")) is not None:
            params[GenAiSemconvKey.REQUEST_TOP_P] = top_p
        if (stop_sequences := inference_config.get("stopSequences")) is not None:
            params[GenAiSemconvKey.REQUEST_STOP_SEQUENCES] = stop_sequences

        if (tool_defs := _extract_tool_definitions(inputs)) is not None:
            params[GenAiSemconvKey.TOOL_DEFINITIONS] = json.dumps(tool_defs)
        return params


def _extract_tool_definitions(inputs: dict[str, Any]) -> list[dict[str, Any]] | None:
    tool_config = inputs.get("toolConfig")
    if not isinstance(tool_config, dict):
        return None
    tools = tool_config.get("tools")
    if not isinstance(tools, list):
        return None

    definitions = []
    for tool in tools:
        tool_spec = tool.get("toolSpec") if isinstance(tool, dict) else None
        if not isinstance(tool_spec, dict):
            continue
        definition: dict[str, Any] = {"type": "function", "name": tool_spec.get("name")}
        if (description := tool_spec.get("description")) is not None:
            definition["description"] = description
        input_schema = tool_spec.get("inputSchema")
        if isinstance(input_schema, dict):
            definition["parameters"] = input_schema.get("json")
        definitions.append(definition)
    return definitions


def _convert_message(msg: dict[str, Any]) -> dict[str, Any]:
    role = msg.get("role", "user")
    content = msg.get("content")

    if isinstance(content, str):
        return {"role": role, "parts": [{"type": "text", "content": content}]}

    if isinstance(content, list):
        parts = []
        has_tool_result = False
        for block in content:
            converted = _convert_block(block)
            parts.append(converted)
            if converted.get("type") == "tool_call_response":
                has_tool_result = True
        # Bedrock uses the "user" role for tool results. Override it to "tool".
        if has_tool_result:
            return {"role": "tool", "parts": parts}
        return {"role": role, "parts": parts}

    return {"role": role, "parts": []}


def _convert_block(block: dict[str, Any]) -> dict[str, Any]:
    if not isinstance(block, dict):
        return {"type": "text", "content": json.dumps(block)}

    if "text" in block:
        return {"type": "text", "content": block.get("text", "")}
    if "image" in block:
        return _convert_image(block["image"])
    if "toolUse" in block:
        tool_use = block["toolUse"]
        return {
            "type": "tool_call",
            "id": tool_use.get("toolUseId", ""),
            "name": tool_use.get("name", ""),
            "arguments": tool_use.get("input"),
        }
    if "toolResult" in block:
        tool_result = block["toolResult"]
        return {
            "type": "tool_call_response",
            "id": tool_result.get("toolUseId", ""),
            "result": json.dumps(tool_result.get("content")),
        }
    # Fallback to text with dumped content block
    return {"type": "text", "content": json.dumps(block)}


def _convert_system_block(block: dict[str, Any]) -> dict[str, Any]:
    if isinstance(block, dict) and "text" in block:
        return {"type": "text", "content": block.get("text", "")}
    return {"type": "text", "content": json.dumps(block)}


def _convert_image(image: dict) -> dict:
    fmt = image.get("format", "")
    source = image.get("source", {})
    data = source.get("bytes")
    if isinstance(data, bytes):
        content = base64.b64encode(data).decode("utf-8")
    else:
        content = data
    return {
        "type": "blob",
        "modality": "image",
        "mime_type": f"image/{fmt}",
        "content": content,
    }
